-- adds is_trading_halted and raw_payload to rwa_issuers, and backfills
-- both for every existing row from the same official api used to seed
-- the table: https://api.xstocks.fi/api/v2/public/assets.
-- verified_source_url already existed and is unchanged.
--
-- raw_payload is the full asset object as returned by the api (name,
-- isin, underlying, trading hours/exchange info, all deployments across
-- every chain, etc.), kept for audit/reference -- the typed columns
-- (issuer_name, asset_type, underlying_symbol, is_trading_halted) are
-- still the ones views and queries should read.

alter table rwa_issuers add column if not exists is_trading_halted boolean;
alter table rwa_issuers add column if not exists raw_payload jsonb;

update rwa_issuers as ri
set is_trading_halted = v.is_trading_halted,
    raw_payload = v.raw_payload
from (
